<h1 class="h2">Trail reviews</h1><p class="muted">Review endpoint is available for this trail.</p><form id="reviewForm" class="card card-body gap-2"><input class="form-control" name="reviewer_name" placeholder="Your name" required minlength="2" maxlength="80"><select class="form-select" name="rating"><option value="5">5 — Excellent</option><option value="4">4 — Good</option><option value="3">3 — Average</option><option value="2">2 — Difficult</option><option value="1">1 — Poor</option></select><textarea class="form-control" name="comment" placeholder="Your review" required minlength="3" maxlength="1000"></textarea><button class="btn btn-forest">Submit review</button></form><div id="reviews" class="mt-3" aria-live="polite"></div><script>const form=document.getElementById('reviewForm'),list=document.getElementById('reviews');async function load(){const r=await fetch('<?= site_url('reviews/'.$trailId) ?>');const a=await r.json();list.innerHTML=a.map(x=>`<div class="card card-body mb-2"><b>${esc(x.reviewer_name)} · ${Number(x.rating)}/5</b><p class="mb-0">${esc(x.comment)}</p></div>`).join('')||'<p>No reviews yet.</p>'}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}form.addEventListener('submit',async e=>{e.preventDefault();const r=await fetch('<?= site_url('api/reviews/'.$trailId) ?>',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','<?= csrf_header() ?>':'<?= csrf_hash() ?>'},body:new URLSearchParams(new FormData(form))});const d=await r.json();if(!r.ok){alert(d.error||JSON.stringify(d.errors||'Unable to submit review'));return;}form.reset();load()});load();</script>
